`,r.jsx(i.em,{children:"Category page in dark mode"})]})]})}function Ev(o={}){const{wrapper:i}=o.components||{};return i?r.jsx(i,{...o,children:r.jsx(Vh,{...o})}):Vh(o)}const Lm=Object.freeze(Object.defineProperty({__proto__:null,default:Ev,frontmatter:Tv},Symbol.toStringTag,{value:"Module"})),Cv={title:"Creating the Echelon Live Class Card UI",date:"11/09/2025",wordCount:259};function Zh(o){const i={em:"em",img:"img",p:"p",...o.components};return r.jsxs(r.Fragment,{children:[r.jsx(i.p,{children:"During this week, my classmates and I had our previously completed tickets for Echelon merged in, which allowed me to proceed with the last remaining UI ticket: the live class cards. These cards were similar to the class cards I had worked on before, but with a few minor changes to the layout. Below is a comparison of the original class card design versus the live class card design:"}),`
