`,r.jsx(i.p,{children:"Graduation is a very big deal for me, so the rest of my time this week was spent preparing for this event and greeting my friends and family who came to visit. The ceremony itself was such a lively and fun event. I got to see so many people I’ve met during my time here walk the finish line. And then, I got to do it myself, which was pretty cool!"}),`
`,r.jsx(i.p,{children:"So, what’s next? This week I also had a chance to have a conversation with Career Development. I’ve contacted them a few times before, but this meeting focused on creating my career strategy plan. We discussed my goals and expectations for the future, and it made me a little more confident knowing all the resources I have at my disposal through the Career Development Team. All that’s left to do now is find a job and live out my software engineering dreams."})]})}function Gv(o={}){const{wrapper:i}=o.components||{};return i?r.jsx(i,{...o,children:r.jsx(Ph,{...o})}):Ph(o)}const Vm=Object.freeze(Object.defineProperty({__proto__:null,default:Gv,frontmatter:Xv},Symbol.toStringTag,{value:"Module"})),Yv={title:"Setting Up Android Studio and Learning Kotlin & Compose",date:"8/24/2025",wordCount:313};function em(o){const i={a:"a",em:"em",img:"img",p:"p",...o.components};return r.jsxs(r.Fragment,{children:[r.jsxs(i.p,{children:["This week, I spent some time diving deeper into the technologies I’ll be using moving forward. Like last week, I continued to research, but this time I decided to actually get my hands dirty. One of my lab instructors recommended checking out an official Android training course, so I chose ",r.jsx(i.a,{href:"https://developer.android.com/courses/android-basics-compose/course",children:"Android Basics with Compose."})]}),`
`,r.jsx(i.p,{children:"The course walks through building Android apps from scratch using Jetpack Compose and the Kotlin programming language."}),`
`,r.jsx(i.p,{children:"So far, I have completed the first unit of this course, where I learned how to create a simple Android app with a user interface that displays images and text. I also got more comfortable with Kotlin’s syntax, which feels a lot like TypeScript, so it clicked pretty quickly for me. After that I set up Android Studio and created my very first project. This helped me get familiar with the IDE, Android’s project structure, and how to use Composable functions to display UI elements like text and images, arranged in layouts like columns, rows, and boxes. The best part was finally emulating the project on a virtual device and seeing my first Android app come to life!"}),`
