`,r.jsx(i.em,{children:"Lemonade Application"})]}),`
`,r.jsx(i.p,{children:"The first month of my capstone project is coming to an end, and I can now move on to working on the Echelon AI Class Card now that a branch has been set up for us to develop in. I’m excited to see what the rest of this journey brings and what I’ll learn along the way!"})]})}function Zv(o={}){const{wrapper:i}=o.components||{};return i?r.jsx(i,{...o,children:r.jsx(tm,{...o})}):tm(o)}const Im=Object.freeze(Object.defineProperty({__proto__:null,default:Zv,frontmatter:Vv},Symbol.toStringTag,{value:"Module"})),Iv={title:"Working on the Echelon Class Card UI",date:"9/7/2025",wordCount:357};function am(o){const i={em:"em",img:"img",li:"li",p:"p",ul:"ul",...o.components};return r.jsxs(r.Fragment,{children:[r.jsx(i.p,{children:"This week marks the beginning of the second month of my capstone project! Now that the coding environment is set up for us and we’ve learned the foundations of Compose and Kotlin, we can get to actually work on the Echelon app. As I mentioned in previous blog posts, I assigned myself a ticket from the Jira board to work on the UI of the class cards. This week I started creating the composable functions that make up this card."}),`
`,r.jsx(i.p,{children:"After reviewing the design in Zeplin and looking at the ticket requirements, I split up the card into the following components:"}),`
